function icon(string $name, string $cls = ''): string
{
    $d = ICONS[$name] ?? ICONS['gear'];
    // Класс ic задаёт базовый размер инлайновой иконки — иначе SVG без width растягивается на всю ширину.
    return '<svg class="ic' . ($cls !== '' ? ' ' . $cls : '') . '" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true" focusable="false">' . $d . '</svg>';
}
